-- Purge gimmick/novelty-equipment exercises from the global seed library
-- (owner_id null, from 20260715055811_seed_free_exercise_db.sql) — see
-- docs/DECISIONS.md 2026-08-07 ("Gimmick-equipment exercise purge").
--
-- Soft-delete only (deleted_at), matching the repo's soft-delete convention:
-- `listExercises`/`getExercise` already filter `deleted_at is null`, so these
-- stop appearing in the picker/library immediately. History/session joins on
-- `exercises(name)` carry no such filter, so past logged sets referencing one
-- of these ids keep rendering their exercise name unchanged.
--
-- 124 rows: all equipment = 'kettlebell' (53), all equipment = 'band' (20),
-- plus 51 gimmick-equipment rows tagged equipment = 'other' (medicine-ball
-- throws/slams, stability/exercise-ball work, ropes, suspension/strap rows,
-- strongman-novelty implements, single-novelty gadgets, and three rows whose
-- equipment is mistagged 'other' but are actually band exercises by
-- instructions). Full grouped name list in the PR body. Ids are deterministic
-- (see scripts/import-free-exercise-db.ts) and never reused.

update "exercises"
set deleted_at = (extract(epoch from now()) * 1000)::bigint,
    updated_at = (extract(epoch from now()) * 1000)::bigint
where owner_id is null
  and id in (
  '00000000-0000-4000-9000-f549628e9d94',
  '00000000-0000-4000-9000-e547b8ecfcb6',
